// Exact rational number arithmetic, replicating Python's fractions.Fraction.
// Integers are stored as BigInt so results match Python's arbitrary precision.

function gcd(a, b) {
  a = a < 0n ? -a : a;
  b = b < 0n ? -b : b;
  while (b !== 0n) {
    const t = a % b;
    a = b;
    b = t;
  }
  return a;
}

export class Fraction {
  // Both arguments must be BigInt (or Number, coerced to BigInt).
  constructor(numerator, denominator = 1n) {
    let n = BigInt(numerator);
    let d = BigInt(denominator);
    if (d === 0n) {
      throw new ZeroDivisionError(
        `Fraction(${n}, 0)`
      );
    }
    if (d < 0n) {
      n = -n;
      d = -d;
    }
    const g = gcd(n, d);
    this.numerator = n / g;
    this.denominator = d / g;
    Object.freeze(this);
  }

  static from(value) {
    if (value instanceof Fraction) return value;
    return new Fraction(BigInt(value), 1n);
  }

  add(other) {
    other = Fraction.from(other);
    return new Fraction(
      this.numerator * other.denominator + other.numerator * this.denominator,
      this.denominator * other.denominator
    );
  }

  mul(other) {
    other = Fraction.from(other);
    return new Fraction(
      this.numerator * other.numerator,
      this.denominator * other.denominator
    );
  }

  // this / other
  div(other) {
    other = Fraction.from(other);
    if (other.numerator === 0n) {
      throw new ZeroDivisionError(
        `Fraction(${this.numerator}, 0)`
      );
    }
    return new Fraction(
      this.numerator * other.denominator,
      this.denominator * other.numerator
    );
  }

  // other / this  (Python's __rtruediv__)
  rdiv(other) {
    if (this.numerator === 0n) {
      throw new ZeroDivisionError(`Fraction(${other}, 0)`);
    }
    return new Fraction(
      BigInt(other) * this.denominator,
      this.numerator
    );
  }

  gt(other) {
    other = Fraction.from(other);
    return this.numerator * other.denominator > other.numerator * this.denominator;
  }

  toString() {
    if (this.denominator === 1n) return this.numerator.toString();
    return `${this.numerator}/${this.denominator}`;
  }
}

export class ZeroDivisionError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ZeroDivisionError';
  }
}

