// Minimal re-implementation of the argparse behavior used by the source script:
//   six required options --a .. --f, each with type=int.
// Supports "--x value" and "--x=value" forms; errors mirror argparse's
// usage/error output on stderr with exit code 2.

import { basename } from 'node:path';

const OPTIONS = ['a', 'b', 'c', 'd', 'e', 'f'];

// Mirrors Python's int(str): optional surrounding whitespace, optional sign,
// digits, single underscores allowed between digits (PEP 515).
const INT_RE = /^[+-]?\d+(?:_\d+)*$/;

function usage(prog) {
  return `usage: ${prog} [-h] ${OPTIONS.map((o) => `--${o} ${o.toUpperCase()}`).join(' ')}`;
}

function fail(prog, message) {
  process.stderr.write(`${usage(prog)}\n${prog}: error: ${message}\n`);
  process.exit(2);
}

export function parseArgs(argv, progPath) {
  const prog = basename(progPath || 'test20.mjs');
  const values = {};
  const extras = [];

  for (let i = 0; i < argv.length; i++) {
    const token = argv[i];
    if (token === '-h' || token === '--help') {
      process.stdout.write(`${usage(prog)}\n\noptions:\n  -h, --help  show this help message and exit\n`);
      process.exit(0);
    }
    let name = null;
    let raw = null;
    if (token.startsWith('--')) {
      const eq = token.indexOf('=');
      if (eq !== -1) {
        name = token.slice(2, eq);
        raw = token.slice(eq + 1);
      } else {
        name = token.slice(2);
        if (i + 1 < argv.length) {
          raw = argv[++i];
        } else {
          fail(prog, `argument --${name}: expected one argument`);
        }
      }
    } else {
      extras.push(token);
      continue;
    }

    if (!OPTIONS.includes(name)) {
      extras.push(token);
      continue;
    }
    if (!INT_RE.test(raw.trim())) {
      fail(prog, `argument --${name}: invalid int value: '${raw}'`);
    }
    values[name] = raw.trim().replace(/_/g, '');
  }

  if (extras.length > 0) {
    fail(prog, `unrecognized arguments: ${extras.join(' ')}`);
  }

  const missing = OPTIONS.filter((o) => !(o in values));
  if (missing.length > 0) {
    fail(prog, `the following arguments are required: ${missing.map((o) => `--${o}`).join(', ')}`);
  }

  return values;
}

