// Entry point — mirrors /workspace/dataset/fractions/test20.py
import { parseArgs } from './lib/argparser.mjs';
import { Fraction } from './lib/fraction.mjs';

const args = parseArgs(process.argv.slice(2), process.argv[1]);

const pyBool = (b) => (b ? 'True' : 'False');

const f1 = new Fraction(args.a, args.b); // API call 1
console.log(String(f1));                 // print line 1
const f2 = new Fraction(args.c, args.d); // API call 2
console.log(String(f2));                 // print line 2
const f3 = new Fraction(args.e, args.f); // API call 3
console.log(String(f3));                 // print line 3

const sum1 = f1.add(f2);                 // API call 4
console.log(String(sum1));               // print line 4
const sum2 = sum1.add(f3);               // API call 5
console.log(String(sum2));               // print line 5

const product1 = f1.mul(f2);             // API call 6
console.log(String(product1));           // print line 6
const product2 = product1.mul(f3);       // API call 7
console.log(String(product2));           // print line 7

// harmonic_mean = 3 / (1/f1 + 1/f2 + 1/f3)
const one = new Fraction(1n, 1n);
const harmonic_mean = new Fraction(3n, 1n).div(
  one.div(f1).add(one.div(f2)).add(one.div(f3))
);
console.log(String(harmonic_mean));      // print line 8

// arithmetic_mean = (f1 + f2 + f3) / 3
const arithmetic_mean = f1.add(f2).add(f3).div(new Fraction(3n, 1n));
console.log(String(arithmetic_mean));    // print line 9

console.log(pyBool(f1.gt(f2)));          // print line 10
console.log(pyBool(f2.gt(f3)));          // print line 11

